            return .{ .context = c };
    }

pub fn maybeTransposeIf(self: *@This(), arg: Expr, state: StateType) Expr {
            switch (arg.data) {
.e_if => |ex| {
return Expr.init(E.If, .{ .yes = self.maybeTransposeIf(ex.yes, state), .no = self.maybeTransposeIf(ex.no, state), .test_ = ex.test_ }, arg.loc);
},
else => {
return visitor(self.context, arg, state);
},
}
    }

pub fn transposeKnownToBeIf(self: *@This(), arg: Expr, state: StateType) Expr {
            return Expr.init(E.If, .{ .yes = self.maybeTransposeIf(arg.data.e_if.yes, state), .no = self.maybeTransposeIf(arg.data.e_if.no, state), .test_ = arg.data.e_if.test_ }, arg.loc);
    }
    pub const Context = ContextType;
    pub const This = @This();
};
}

pub fn locAfterOp(e: E.Binary) logger.Loc {
        if ((e.left.loc.start < e.right.loc.start)) {
            return e.right.loc;
        } else {
            return e.left.loc;
        }
}

